"""小さな CSV の金額を合計します。"""
import csv
import sys
from pathlib import Path


def total(path):
    with path.open(encoding="utf-8") as source:
        return sum(int(row["amount"]) for row in csv.DictReader(source))


if __name__ == "__main__":
    print(total(Path(sys.argv[1])))

